package com.tilepacks;

import com.google.common.base.Strings;
import lombok.Value;
import lombok.experimental.NonFinal;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;

/**
 * This class is responsible for all functions that interface with or modify the configs related to global filters.
 */
@Slf4j
@Value
public class FilterManager {
    private static final String CONFIG_GROUP = "tilePacks";
    private static final String SHOW_VISIBLE = "showVisible";
    private static final String SHOW_INVISIBLE = "showInvisible";

    @NonFinal
    private boolean showVisible;
    @NonFinal
    private boolean showInvisible;

    private final ConfigManager configManager;

    @Inject
    FilterManager( ConfigManager configManager) {
        this.configManager = configManager;
        this.loadFilters();
    }

    //loads the filters from the config
    private void loadFilters() {
        String showVisibleConfig = configManager.getConfiguration(CONFIG_GROUP, SHOW_VISIBLE);

        if (Strings.isNullOrEmpty(showVisibleConfig)) {
            this.showVisible = true;
        } else {
            this.showVisible = Boolean.parseBoolean(showVisibleConfig);
        }

        String showInvisibleConfig = configManager.getConfiguration(CONFIG_GROUP, SHOW_INVISIBLE);

        if (Strings.isNullOrEmpty(showInvisibleConfig)) {
            this.showInvisible = false;
        } else {
            this.showInvisible = Boolean.parseBoolean(showInvisibleConfig);
        }
    }

    //sets showVisible in the config
    public void setShowVisible(boolean showVisible) {
        this.showVisible = showVisible;
        configManager.setConfiguration(CONFIG_GROUP, SHOW_VISIBLE, showVisible);
    }

    //returns the value of showVisible
    public boolean getShowVisible() {
        return this.showVisible;
    }

    //sets showInvisible in the config
    public void setShowInvisible(boolean showInvisible) {
        this.showInvisible = showInvisible;
        configManager.setConfiguration(CONFIG_GROUP, SHOW_INVISIBLE, showInvisible);
    }

    //returns the value of showVisible
    public boolean getShowInvisible() {
        return this.showInvisible;
    }
}

package com.tilepacks;

import com.google.common.collect.ArrayListMultimap;
import com.google.common.collect.ImmutableListMultimap;
import com.google.common.collect.ListMultimap;
import com.tilepacks.data.ColorTileMarker;
import com.tilepacks.data.GroundMarkerPoint;
import com.tilepacks.data.TilePack;
import lombok.Getter;
import lombok.Value;
import lombok.experimental.NonFinal;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

import javax.inject.Inject;
import java.awt.Color;
import java.util.*;
import java.util.stream.Collectors;

/**
 * This class is responsible for translating the tile packs into drawable points
 */
@Slf4j
@Value
public class PointManager {

    @Getter
    @NonFinal
    private volatile ImmutableListMultimap<WorldView, ColorTileMarker> points = ImmutableListMultimap.of();

    @NonFinal
    private Map<Integer, List<GroundMarkerPoint>> activePointsByRegion;

    private final TilePackManager tilePackManager;
    private final Client client;

    @Inject
    PointManager(TilePackManager tilePackManager, Client client) {
        this.tilePackManager = tilePackManager;
        this.client = client;
    }

    //loads the points from the packs for the players active regions
    public synchronized void loadPoints() {
        activePointsByRegion = null;
        ListMultimap<WorldView, ColorTileMarker> updatedPoints = ArrayListMultimap.create();

        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null)
        {
            points = ImmutableListMultimap.copyOf(updatedPoints);
            return;
        }

        addWorldViewPoints(updatedPoints, worldView);

        for (WorldEntity we : worldView.worldEntities())
        {
            addWorldViewPoints(updatedPoints, we.getWorldView());
        }

        points = ImmutableListMultimap.copyOf(updatedPoints);
    }

    public synchronized void loadWorldViewPoints(WorldView worldView)
    {
        ListMultimap<WorldView, ColorTileMarker> updatedPoints = ArrayListMultimap.create(points);
        updatedPoints.removeAll(worldView);
        addWorldViewPoints(updatedPoints, worldView);
        points = ImmutableListMultimap.copyOf(updatedPoints);
    }

    private void addWorldViewPoints(ListMultimap<WorldView, ColorTileMarker> updatedPoints, WorldView worldView)
    {
        int[] regions = worldView.getMapRegions();
        if (regions == null)
        {
            return;
        }

        for (int regionId : regions)
        {
            Collection<GroundMarkerPoint> regionPoints = getActivePoints(regionId);
            Collection<ColorTileMarker> colorTileMarkers = translateToColorTileMarker(worldView, regionPoints);
            updatedPoints.putAll(worldView, colorTileMarkers);
        }
    }

    //gets the active points for a region, loading and indexing all enabled packs once.
    synchronized List<GroundMarkerPoint> getActivePoints(int regionId) {
        if (activePointsByRegion == null)
        {
            activePointsByRegion = new HashMap<>();
            Set<Integer> enabledPacks = new HashSet<>(tilePackManager.getEnabledPacks());
            for (Map.Entry<Integer, TilePack> pack : tilePackManager.getTilePacks().entrySet()) {
                if (!enabledPacks.contains(pack.getKey())) {
                    continue;
                }

                List<GroundMarkerPoint> markers = pack.getValue().parsedPackTiles;
                if (markers == null) {
                    log.warn("Skipping tile pack {} because its tile data is invalid", pack.getKey());
                    continue;
                }
                for (GroundMarkerPoint marker : markers)
                {
                    Color markerColor = marker.getColor();
                    if (markerColor == null) {
                        markerColor = pack.getValue().defaultColor == null
                                ? Color.YELLOW
                                : pack.getValue().defaultColor;
                    }
                    GroundMarkerPoint resolvedMarker = new GroundMarkerPoint(
                            marker.getRegionId(), marker.getRegionX(), marker.getRegionY(), marker.getZ(),
                            markerColor, marker.getLabel());
                    activePointsByRegion
                            .computeIfAbsent(resolvedMarker.getRegionId(), key -> new ArrayList<>())
                            .add(resolvedMarker);
                }
            }

        }

        List<GroundMarkerPoint> regionPoints = activePointsByRegion.get(regionId);
        if (regionPoints == null) {
            return Collections.emptyList();
        }
        return regionPoints;
    }

    private Collection<ColorTileMarker> translateToColorTileMarker(WorldView wv, Collection<GroundMarkerPoint> points)
    {
        if (points.isEmpty())
        {
            return Collections.emptyList();
        }

        return points.stream()
                .map(point -> new ColorTileMarker(
                        WorldPoint.fromRegion(point.getRegionId(), point.getRegionX(), point.getRegionY(), point.getZ()),
                        point.getColor(), point.getLabel()))
                .flatMap(colorTile ->
                {
                    final Collection<WorldPoint> localWorldPoints = WorldPoint.toLocalInstance(wv, colorTile.getWorldPoint());
                    return localWorldPoints.stream().map(wp -> new ColorTileMarker(wp, colorTile.getColor(), colorTile.getLabel()));
                })
                .collect(Collectors.toList());
    }
}

package com.tilepacks;

import com.tilepacks.data.GroundMarkerPoint;
import com.tilepacks.data.TilePack;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxPanelManager;

import javax.inject.Inject;
import java.awt.Color;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Consumer;

/** Handles pack scoped scene tile editing. */
public class TilePackEditingManager {
    private final Client client;
    private final TilePackManager tilePackManager;
    private final PointManager pointManager;
    private final TilePacksConfig config;
    private final ChatboxPanelManager chatboxPanelManager;
    private final ClientThread clientThread;

    private volatile Integer editingPackId;

    @Inject
    TilePackEditingManager(Client client, TilePackManager tilePackManager,
                           PointManager pointManager, TilePacksConfig config,
                           ChatboxPanelManager chatboxPanelManager, ClientThread clientThread) {
        this.client = client;
        this.tilePackManager = tilePackManager;
        this.pointManager = pointManager;
        this.config = config;
        this.chatboxPanelManager = chatboxPanelManager;
        this.clientThread = clientThread;
    }

    /** Sets the pack currently being edited */
    public synchronized void editPack(Integer packId) {
        if (packId == null || !tilePackManager.getTilePacks().containsKey(packId)) {
            editingPackId = null;
            return;
        }
        editingPackId = packId;
    }

    public synchronized void stopEditing() {
        editingPackId = null;
    }

    public Integer getEditingPackId() {
        return editingPackId;
    }

    public synchronized void onMenuEntryAdded(MenuEntryAdded event) {
        Integer packId = editingPackId;
        if (!shouldHandleMenuEntry(packId, client.isKeyPressed(KeyCode.KC_SHIFT), event.getMenuEntry().getType())) {
            return;
        }

        int worldViewId = event.getMenuEntry().getWorldViewId();
        WorldView worldView = client.getWorldView(worldViewId);
        if (worldView == null) {
            return;
        }

        Tile selectedTile = worldView.getSelectedSceneTile();
        if (selectedTile == null) {
            return;
        }

        WorldPoint point = WorldPoint.fromLocalInstance(client, selectedTile.getLocalLocation());
        if (point == null) {
            return;
        }

        TilePack pack = tilePackManager.getTilePacks().get(packId);
        if (pack == null) {
            return;
        }

        boolean containsTile = pack.parsedPackTiles.contains(new GroundMarkerPoint(point.getRegionID(), point.getRegionX(),
                point.getRegionY(), point.getPlane(), null, null));
        String packName = pack.packName == null ? "" : pack.packName;
        client.createMenuEntry(-1)
                .setOption((containsTile ? "Remove from '" + packName + "' pack" : "Mark in '" + packName + "' pack") )
                .setWorldViewId(worldViewId)
                .setType(MenuAction.RUNELITE)
                .onClick(menuEvent -> toggleTile(packId, point));

        if (containsTile) {
            client.createMenuEntry(-1)
                    .setOption("Edit label in '" + packName + "' pack")
                    .setWorldViewId(worldViewId)
                    .setType(MenuAction.RUNELITE)
                    .onClick(menuEvent -> promptForLabel(packId, point));
        }
    }

    static boolean shouldHandleMenuEntry(Integer editingPackId, boolean shiftPressed, MenuAction action) {
        return editingPackId != null && shiftPressed
                && (action == MenuAction.WALK || action == MenuAction.SET_HEADING);
    }

    synchronized boolean toggleTile(Integer packId, WorldPoint point) {
        if (!Objects.equals(editingPackId, packId)) {
            return false;
        }

        TilePack pack = tilePackManager.getTilePacks().get(packId);
        if (pack == null) {
            return false;
        }

        GroundMarkerPoint newPoint = new GroundMarkerPoint(point.getRegionID(), point.getRegionX(),
                point.getRegionY(), point.getPlane(), resolveTileColor(pack), null);

        int index = pack.indexOf(point);
        if (index >= 0) {
            pack.parsedPackTiles.remove(index);
        } else {
            pack.parsedPackTiles.add(newPoint);
        }

        saveTiles(packId, pack.parsedPackTiles);
        return true;
    }

    /** Opens the chatbox prompt for a tile's label, pre-filled with the current one. */
    protected void promptForLabel(Integer packId, WorldPoint point) {
        final String currentLabel;
        synchronized (this) {
            if (!Objects.equals(editingPackId, packId)) {
                return;
            }
            TilePack pack = tilePackManager.getTilePacks().get(packId);

            int index = pack.indexOf(point);
            if (index < 0) {
                return;
            }
            currentLabel = pack.parsedPackTiles.get(index).getLabel();
        }

        // Opened outside the lock so the prompt never holds up menu handling
        chatboxPanelManager.openTextInput("Tile label")
                .value(currentLabel == null ? "" : currentLabel)
                .onDone((Consumer<String>) input -> clientThread.invoke(() -> {
                    setTileLabel(packId, point, input);
                }))
                .build();
    }

    /** Sets or clears the label on an existing tile. A blank label clears it. */
    synchronized boolean setTileLabel(Integer packId, WorldPoint point, String label) {
        // The prompt can outlive the state it was opened in: re-check everything
        if (!Objects.equals(editingPackId, packId)) {
            return false;
        }
        TilePack pack = tilePackManager.getTilePacks().get(packId);

        int index = pack.indexOf(point);
        if (index < 0) {
            return false; // tile was removed while the prompt was open
        }

        String normalized = label == null ? null : label.trim();
        if (normalized != null && normalized.isEmpty()) {
            normalized = null;
        }

        GroundMarkerPoint existing = pack.parsedPackTiles.get(index);
        if (Objects.equals(existing.getLabel(), normalized)) {
            return false; // nothing changed, skip the save
        }

        pack.parsedPackTiles.set(index, new GroundMarkerPoint(existing.getRegionId(), existing.getRegionX(),
                existing.getRegionY(), existing.getZ(), existing.getColor(), normalized));

        saveTiles(packId, pack.parsedPackTiles);
        return true;
    }

    /** Shared persistence step for any change to a pack's tiles. */
    private void saveTiles(Integer packId, List<GroundMarkerPoint> points) {
        tilePackManager.updatePackTiles(packId, points);
        pointManager.loadPoints();
    }

    private static GroundMarkerPoint toCoordinate(WorldPoint point) {
        return new GroundMarkerPoint(point.getRegionID(), point.getRegionX(), point.getRegionY(), point.getPlane(), null, null);
    }

    private Color resolveTileColor(TilePack pack) {
        if (pack.defaultColor != null) {
            return pack.defaultColor;
        }
        if (config.overrideColorActive()) {
            return config.overrideColor();
        }
        if (!pack.parsedPackTiles.isEmpty()) {
            Color firstInPack = pack.parsedPackTiles.get(0).getColor();
            if (firstInPack != null) {
                return firstInPack;
            }
        }
        return Color.YELLOW;
    }
}

package com.tilepacks;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;

/** Validation for user-supplied Ground Markers tile imports. */
public final class TilePackImportValidator {
    private TilePackImportValidator() {
    }

    public static boolean isValid(String tilesJson, Gson gson) {
        if (tilesJson == null || tilesJson.isEmpty() || gson == null) {
            return false;
        }

        try {
            JsonElement root = gson.fromJson(tilesJson, JsonElement.class);
            if (root == null || !root.isJsonArray() || root.getAsJsonArray().size() == 0) {
                return false;
            }

            for (JsonElement element : root.getAsJsonArray()) {
                if (element == null || !element.isJsonObject()) {
                    return false;
                }
                JsonObject point = element.getAsJsonObject();
                Integer regionId = readInteger(point, "regionId");
                Integer regionX = readInteger(point, "regionX");
                Integer regionY = readInteger(point, "regionY");
                Integer plane = readInteger(point, "z");
                if (regionId == null || regionId < 0 || regionId > 0xFFFF
                        || regionX == null || regionX < 0 || regionX > 63
                        || regionY == null || regionY < 0 || regionY > 63
                        || plane == null || plane < 0 || plane > 3) {
                    return false;
                }
            }
            return true;
        } catch (RuntimeException e) {
            return false;
        }
    }

    private static Integer readInteger(JsonObject object, String key) {
        if (!object.has(key)) {
            return null;
        }
        JsonElement element = object.get(key);
        if (element == null || !element.isJsonPrimitive()) {
            return null;
        }
        JsonPrimitive primitive = element.getAsJsonPrimitive();
        if (!primitive.isNumber()) {
            return null;
        }
        try {
            return Integer.valueOf(primitive.getAsString());
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

package com.tilepacks;

import com.google.common.base.Strings;
import com.google.common.reflect.TypeToken;
import com.google.gson.Gson;
import com.tilepacks.data.GroundMarkerPoint;
import com.tilepacks.data.TilePack;
import lombok.Value;
import lombok.experimental.NonFinal;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import java.awt.Color;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * This class is responsible for all functions that interface with or modify tile packs
 */
@Slf4j
@Value
public class TilePackManager {
    private static final String CONFIG_GROUP = "tilePacks";
    private static final String CUSTOM_ID = "customId";
    private static final String PACK_PREFIX = "pack_";
    private static final String PACKS_PREFIX = "packs";
    private static final Type TILE_LIST_TYPE = new TypeToken<List<GroundMarkerPoint>>() {
    }.getType();

    @NonFinal
    private Map<Integer, TilePack> tilePacks = new HashMap<Integer, TilePack>();
    @NonFinal
    private List<Integer> enabledPacks = new ArrayList<Integer>();
    //These are the default packs that the user has edited, which makes a clone of the default.
    @NonFinal
    private Set<Integer> fullOverridePackIds = new HashSet<Integer>();

    private final Gson gson;
    private final ConfigManager configManager;

    @Inject
    TilePackManager(Gson gson, ConfigManager configManager) {
        this.gson = gson;
        this.configManager = configManager;

        this.loadEnabledPacks();
        this.loadPacks();
    }

    //loads the packs from the json file
    private void loadPacks() {
        try (InputStream in = getClass().getResourceAsStream("tilePacks.jsonc")) {
            final InputStreamReader data = new InputStreamReader(in, StandardCharsets.UTF_8);
            final Type type = new TypeToken<Map<Integer, TilePack>>() {
            }.getType();
            Map<Integer, TilePack> parsed = gson.fromJson(data, type);
            for (TilePack savedPack : loadSavedPacks().values()) {
                TilePack resourcePack = parsed.get(savedPack.id);
                if (isFullPackRecord(savedPack)) {
                    parsed.put(savedPack.id, savedPack);
                    fullOverridePackIds.add(savedPack.id);
                } else if (resourcePack != null) {
                    resourcePack.visible = savedPack.visible;
                }
            }

            for (TilePack pack : parsed.values()) {
                pack.parsedPackTiles = parseTiles(pack.packTiles);
            }

            tilePacks = parsed;
        } catch (Exception e) {
            log.error("error loading packs from json, this is likely due to a bad json file.", e);
        }
    }

    private Map<Integer, TilePack> loadSavedPacks() {
        Map<Integer, TilePack> savedPacks = new HashMap<Integer, TilePack>();
        String wholePrefix = ConfigManager.getWholeKey(CONFIG_GROUP, null, PACK_PREFIX);
        for (String key : configManager.getConfigurationKeys(wholePrefix)) {
            String packId = key.substring(wholePrefix.length());
            try {
                Integer id = Integer.valueOf(packId);
                String json = configManager.getConfiguration(CONFIG_GROUP, PACK_PREFIX + id);
                TilePack pack = gson.fromJson(json, TilePack.class);
                if (pack != null) {
                    savedPacks.put(id, pack);
                }
            } catch (RuntimeException e) {
                log.warn("Unable to load tile pack config {}", key, e);
            }
        }
        return savedPacks;
    }

    /**
     * Parses a pack's tile JSON. Null entries are dropped.
     * @return an unmodifiable list, or null when the JSON is missing or unreadable
     */
    public List<GroundMarkerPoint> parseTiles(String packTiles) {
        if (packTiles == null) {
            return null;
        }

        try {
            List<GroundMarkerPoint> points = gson.fromJson(packTiles, TILE_LIST_TYPE);
            if (points == null) {
                return null;
            }
            List<GroundMarkerPoint> parsed = new ArrayList<>(points);
            parsed.removeIf(Objects::isNull);
            return parsed;
        } catch (RuntimeException e) {
            log.warn("Unable to parse tile data", e);
            return null;
        }
    }

    private void savePack(TilePack pack) {
        configManager.setConfiguration(CONFIG_GROUP, PACK_PREFIX + pack.id, gson.toJson(pack));
    }

    //saves a pack id to the saved config of enabled packs
    public void addEnabledPack(Integer packId) {
        enabledPacks.add(packId);

        String json = gson.toJson(enabledPacks);
        configManager.setConfiguration(CONFIG_GROUP, PACKS_PREFIX, json);
    }

    //removes a pack id from the saved config of enabled packs
    public void removeEnabledPack(Integer packId) {
        enabledPacks.remove(packId);
        if (enabledPacks.isEmpty()) {
            configManager.unsetConfiguration(CONFIG_GROUP, PACKS_PREFIX);
            return;
        }

        String json = gson.toJson(enabledPacks);
        configManager.setConfiguration(CONFIG_GROUP, PACKS_PREFIX, json);
    }

    //gets a list of all enabled pack ids
    private void loadEnabledPacks() {
        String json = configManager.getConfiguration(CONFIG_GROUP, PACKS_PREFIX);

        log.debug("json {}", json);
        if (Strings.isNullOrEmpty(json)) {
            return;
        }
        enabledPacks = gson.fromJson(json, new TypeToken<List<Integer>>() {
        }.getType());
    }

    //gets the custom id the user is currently on
    //each pack the user adds needs a unique index, so we need to manage that
    public Integer loadCustomId() {
        String json = configManager.getConfiguration(CONFIG_GROUP, CUSTOM_ID);

        if (Strings.isNullOrEmpty(json)) {
            //default to 9999 because we add 1, and I want it to start at an even 10k.
            return 9999;
        }
        return gson.fromJson(json, new TypeToken<Integer>() {
        }.getType());
    }

    /**
     * saves a custom pack to the users config
     * @return the ID of the new pack
     */
    public Integer addCustomPack(String name, String tiles) {
        Integer customId = loadCustomId() + 1;
        TilePack pack = new TilePack(customId, name, tiles);
        pack.parsedPackTiles = parseTiles(tiles);
        savePack(pack);
        configManager.setConfiguration(CONFIG_GROUP, CUSTOM_ID, customId);

        addEnabledPack(pack.id);
        tilePacks.put(pack.id, pack);
        return pack.id;
    }

    //removes a custom pack from the users config
    public void removeCustomPack(Integer packId) {
        //unsubscribe the pack before removing it.
        removeEnabledPack(packId);
        configManager.unsetConfiguration(CONFIG_GROUP, PACK_PREFIX + packId);
        tilePacks.remove(packId);
    }

    public void updatePack(TilePack pack) {
        if (pack.id >= 10000 || fullOverridePackIds.contains(pack.id)) {
            savePack(pack);
        } else {
            savePack(new TilePack(pack.id, pack.visible));
        }
    }

    /**
     * Returns the manager-owned pack and creates a full saved override the first time a bundled
     * pack is opened for editing.
     */
    public TilePack preparePackForEditing(Integer packId) {
        TilePack pack = tilePacks.get(packId);
        if (pack == null || packId >= 10000 || fullOverridePackIds.contains(packId)) {
            return pack;
        }

        TilePack override = new TilePack();
        override.id = pack.id;
        override.packName = pack.packName;
        override.link = pack.link;
        override.packTiles = pack.packTiles;
        override.parsedPackTiles = pack.parsedPackTiles;
        override.defaultColor = pack.defaultColor;
        override.visible = pack.visible;

        savePack(override);
        tilePacks.put(packId, override);
        fullOverridePackIds.add(packId);
        return override;
    }

    /** Updates only the title of the manager-owned pack and saves its complete record. */
    public void updatePackTitle(Integer packId, String title) {
        TilePack pack = preparePackForEditing(packId);
        if (pack == null) {
            return;
        }

        pack.packName = title;
        savePack(pack);
        fullOverridePackIds.add(packId);
    }

    /** Saves the per-pack default color */
    public void updatePackDefaultColor(Integer packId, Color color) {
        TilePack pack = preparePackForEditing(packId);
        if (pack == null) {
            return;
        }
        pack.defaultColor = color;
        savePack(pack);
        fullOverridePackIds.add(packId);
    }

    /** Saves tile JSON */
    public void updatePackTiles(Integer packId, List<GroundMarkerPoint> points) {
        TilePack pack = preparePackForEditing(packId);
        if (pack == null) {
            return;
        }

        List<GroundMarkerPoint> snapshot = new ArrayList<>(points);
        pack.packTiles = gson.toJson(snapshot, TILE_LIST_TYPE);
        pack.parsedPackTiles = snapshot;
        savePack(pack);
        fullOverridePackIds.add(packId);
    }

    private boolean isFullPackRecord(TilePack pack) {
        return pack.packName != null || pack.link != null || pack.packTiles != null || pack.defaultColor != null;
    }

    public boolean isPackEnabled(Integer packId) {
        return enabledPacks.contains(packId);
    }
}

package com.tilepacks;

import com.google.common.base.Strings;
import com.google.common.reflect.TypeToken;
import com.google.gson.Gson;
import com.tilepacks.data.TilePack;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

@Slf4j
public class TilePackMigrations {
    private static final String CONFIG_GROUP = "tilePacks";
    private static final String PACK_PREFIX = "pack_";
    private static final String CUSTOM_PACKS = "customPacks";
    private static final String TILE_PACK_CONFIGS = "tilePackConfigs";
    private static final String TILE_PACKS_VERSION = "tilePacksVersion";
    // More for reference than actual use.
    private static final int CURRENT_VERSION = 3;

    private final Gson gson;
    private final ConfigManager configManager;
    private final ChatMessageManager chatMessageManager;

    @Inject
    TilePackMigrations(Gson gson, ConfigManager configManager,
                       ChatMessageManager chatMessageManager) {
        this.gson = gson;
        this.configManager = configManager;
        this.chatMessageManager = chatMessageManager;
    }

    void migrateToLatest() {
        int version = loadVersion();

        if (version < 2) {
            migrateV1ToV2();
            saveVersion(2);
        }
        if (version < 3) {
            migrateV2toV3();
            saveVersion(3);
        }
    }

    private int loadVersion() {
        String version = configManager.getConfiguration(CONFIG_GROUP, TILE_PACKS_VERSION);
        return Strings.isNullOrEmpty(version) ? 1 : Integer.parseInt(version);
    }

    private void saveVersion(int version) {
        configManager.setConfiguration(CONFIG_GROUP, TILE_PACKS_VERSION, version);
    }

    private void migrateV1ToV2() {
        String customPacksJson = configManager.getConfiguration(CONFIG_GROUP, CUSTOM_PACKS);
        String tilePackConfigsJson = configManager.getConfiguration(CONFIG_GROUP, TILE_PACK_CONFIGS);

        if (Strings.isNullOrEmpty(customPacksJson) && Strings.isNullOrEmpty(tilePackConfigsJson)) {
            return;
        }

        Map<Integer, LegacyTilePack> customPacks = parseMap(customPacksJson,
                new TypeToken<Map<Integer, LegacyTilePack>>() { }.getType());
        Map<Integer, LegacyTilePackConfig> tilePackConfigs = parseMap(tilePackConfigsJson,
                new TypeToken<Map<Integer, LegacyTilePackConfig>>() { }.getType());

        Set<Integer> ids = new HashSet<>();
        ids.addAll(customPacks.keySet());
        ids.addAll(tilePackConfigs.keySet());

        for (Integer id : ids) {
            LegacyTilePack customPack = customPacks.get(id);
            LegacyTilePackConfig config = tilePackConfigs.get(id);
            boolean visible = config == null || config.visible;

            TilePack pack;
            if (customPack == null) {
                pack = new TilePack(id, visible);
            } else {
                pack = new TilePack(id, customPack.packName, customPack.link, customPack.packTiles);
                pack.visible = visible;
            }

            configManager.setConfiguration(CONFIG_GROUP, PACK_PREFIX + id, gson.toJson(pack));
        }

        verifySavedPacks(ids);

        configManager.unsetConfiguration(CONFIG_GROUP, CUSTOM_PACKS);
        configManager.unsetConfiguration(CONFIG_GROUP, TILE_PACK_CONFIGS);
    }

    private void verifySavedPacks(Set<Integer> ids) {
        for (Integer id : ids) {
            String json = configManager.getConfiguration(CONFIG_GROUP, PACK_PREFIX + id);
            if (Strings.isNullOrEmpty(json)) {
                throw new IllegalStateException("Saved tile pack config is missing for id " + id);
            }

            TilePack pack = gson.fromJson(json, TilePack.class);
            if (pack == null || !id.equals(pack.id)) {
                throw new IllegalStateException("Saved tile pack config is invalid for id " + id);
            }
        }
    }

    private <T> Map<Integer, T> parseMap(String json, Type type) {
        if (Strings.isNullOrEmpty(json)) {
            return new HashMap<>();
        }
        Map<Integer, T> parsed = gson.fromJson(json, type);
        return parsed == null ? new HashMap<>() : parsed;
    }

    private static class LegacyTilePack {
        private Integer id;
        private String packName;
        private String link;
        private String packTiles;
    }

    private static class LegacyTilePackConfig {
        private Integer packId;
        private boolean visible;
    }

    private void migrateV2toV3() {
        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage("Tile packs now supports per pack edits. Click the pencil icon on an enabled pack to try it out.")
                .build());
        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage("Tile packs new global tile opacity override now available. It's in the plugin config, not the main panel.")
                .build());
    }
}

package com.tilepacks;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup(TilePacksConfig.GROUP)
public interface TilePacksConfig extends Config {
    String GROUP = "tilepacks";

    @ConfigItem(
            keyName = "hidePlugin",
            name = "Hide on toolbar",
            description = "When checked, the plugin will not appear in the tool bar"
    )
    default boolean hidePlugin() {
        return false;
    }

    @ConfigItem(
            keyName = "showLabels",
            name = "Show Labels",
            description = "When checked, labels will render as defined in each pack"
    )
    default boolean showLabels() {
        return true;
    }

    @ConfigItem(
            keyName = "overrideColorActive",
            name = "Override Color Active",
            description = "When checked, all tiles will render as the selected color"
    )
    default boolean overrideColorActive() {
        return false;
    }

    @Alpha
    @ConfigItem(
            keyName = "overrideColor",
            name = "Override Color",
            description = "If Use Override Color is checked, all tiles will be this color."
    )
    default Color overrideColor() {
        return Color.YELLOW;
    }

    @ConfigItem(
            keyName = "drawTilesOnMinimmap",
            name = "Draw tiles on minimap",
            description = "Configures whether tile packs tiles should be drawn on minimap"
    )
    default boolean drawTilesOnMinimmap() {
        return false;
    }

    @ConfigItem(
            keyName = "borderWidth",
            name = "Border Width",
            description = "Width of the marked tile border"
    )
    default double borderWidth() {
        return 2;
    }

    @ConfigItem(
            keyName = "fillOpacity",
            name = "Fill Opacity",
            description = "Opacity of the tile fill color"
    )
    default int fillOpacity() {
        return 50;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(
            keyName = "overrideOpacity",
            name = "Override Opacity",
            description = "If Override Opacity Active is checked, all tile lines will use this opacity (0-100)"
    )
    default int overrideOpacity() {
        return 100;
    }

    @ConfigItem(
            keyName = "overrideOpacityActive",
            name = "Override Opacity Active",
            description = "When checked, all tile lines will render with the selected opacity"
    )
    default boolean overrideOpacityActive() {
        return false;
    }
}

package com.tilepacks;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.tilepacks.ui.overlay.GroundMarkerMinimapOverlay;
import com.tilepacks.ui.overlay.GroundMarkerOverlay;
import com.tilepacks.ui.panel.TilePacksPanel;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.WorldViewLoaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.image.BufferedImage;

@Slf4j
@PluginDescriptor(
        name = "Tile Packs"
)
public class TilePacksPlugin extends Plugin {
    @Inject
    private Client client;
    @Inject
    private TilePacksConfig config;
    @Inject
    private ConfigManager configManager;
    @Inject
    private Gson gson;
    @Inject
    private ClientToolbar clientToolbar;
    @Inject
    private OverlayManager overlayManager;
    @Inject
    private ChatMessageManager chatMessageManager;
    @Inject
    private ColorPickerManager colorPickerManager;
    @Inject
    private ChatboxPanelManager chatboxPanelManager;
    @Inject
    private ClientThread clientThread;

    private GroundMarkerMinimapOverlay minimapOverlay;
    private GroundMarkerOverlay overlay;
    private TilePackManager tilePackManager;
    private TilePackEditingManager tilePackEditingManager;
    private PointManager pointManager;
    private FilterManager filterManager;
    private TilePacksPanel panel;
    private NavigationButton navButton;

    @Override
    protected void startUp() throws Exception {
        try {
            new TilePackMigrations(gson, configManager, chatMessageManager).migrateToLatest();
        } catch (Exception e) {
            log.error("Unable to migrate Tile Packs configuration", e);
            chatMessageManager.queue(QueuedMessage.builder()
                    .type(ChatMessageType.CONSOLE)
                    .runeLiteFormattedMessage("Tile Packs failed to migrate to latest version. Please report this issue.")
                    .build());
            return;
        }

        tilePackManager = new TilePackManager(gson, configManager);
        pointManager = new PointManager(tilePackManager, client);
        tilePackEditingManager = new TilePackEditingManager(client, tilePackManager, pointManager, config, chatboxPanelManager, clientThread);
        filterManager = new FilterManager(configManager);

        overlay = new GroundMarkerOverlay(pointManager, client, config);
        minimapOverlay = new GroundMarkerMinimapOverlay(pointManager, client, config);
        overlayManager.add(overlay);
        overlayManager.add(minimapOverlay);
        panel = new TilePacksPanel(tilePackManager, tilePackEditingManager, pointManager, filterManager, chatMessageManager,
                gson, client, colorPickerManager, config);

        final BufferedImage icon = ImageUtil.loadImageResource(TilePacksPlugin.class, "tilepacks_icon.png");

        navButton = NavigationButton.builder()
                .tooltip("Tile Packs")
                .icon(icon)
                .priority(4)//how is this determined? Could it be a config?
                .panel(panel)
                .build();

        pointManager.loadPoints();

        log.debug("Tile Packs Plugin started");
        if (config.hidePlugin()) {
            return;
        }

        clientToolbar.addNavigation(navButton);

    }

    @Override
    protected void shutDown() throws Exception {
        if (panel != null) {
            panel.cancelPendingTitleEdit();
        }
        if (tilePackEditingManager != null) {
            tilePackEditingManager.stopEditing();
        }
        overlayManager.remove(overlay);
        overlayManager.remove(minimapOverlay);
        clientToolbar.removeNavigation(navButton);
        log.debug("Tile Packs Plugin stopped");
    }

    @Subscribe
    public void onConfigChanged(final ConfigChanged event) {
        if (event.getGroup().equals(TilePacksConfig.GROUP)) {
            switch (event.getKey()) {
                case "hidePlugin":
                    if (config.hidePlugin()) {
                        clientToolbar.removeNavigation(navButton);
                    } else {
                        clientToolbar.addNavigation(navButton);
                    }
                    break;
            }
        }
    }

    @Subscribe
    public void onProfileChanged(ProfileChanged profileChanged)
    {
        if (panel != null) {
            panel.cancelPendingTitleEdit();
        } else if (tilePackEditingManager != null) {
            tilePackEditingManager.stopEditing();
        }
        pointManager.loadPoints();
    }

    @Subscribe
    public void onWorldViewLoaded(WorldViewLoaded event) {
        log.debug("Changing world view");
        // map region has just been updated
        pointManager.loadWorldViewPoints(event.getWorldView());
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (tilePackEditingManager != null) {
            tilePackEditingManager.onMenuEntryAdded(event);
        }
    }

    @Provides
    TilePacksConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(TilePacksConfig.class);
    }
}

