package com.tilepacks.data;

import lombok.EqualsAndHashCode;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

import javax.annotation.Nullable;
import java.awt.*;
import java.util.Objects;

/**
 * Used for serialization of ground marker points.
 */
@Value
@EqualsAndHashCode(exclude = {"color", "label"})
public class GroundMarkerPoint {
    public int regionId;
    public int regionX;
    public int regionY;
    public int z;
    @Nullable
    public Color color;
    @Nullable
    public String label;

    public GroundMarkerPoint(int regionId, int regionX, int regionY, int z, @Nullable Color color, @Nullable String label) {
        this.regionId = regionId;
        this.regionX = regionX;
        this.regionY = regionY;
        this.z = z;
        this.color = color;
        this.label = label;
    }

    public boolean matchesLocation(GroundMarkerPoint point) {
        return point.getRegionId() == regionId
                && point.getRegionX() == regionX
                && point.getRegionY() == regionY
                && point.getZ() == z;
    }

    public boolean matchesLocation(WorldPoint point) {
        return point.getRegionID() == regionId
                && point.getRegionX() == regionX
                && point.getRegionY() == regionY
                && point.getPlane() == z;
    }
}

package com.tilepacks.data;

import net.runelite.api.coords.WorldPoint;

import javax.annotation.Nullable;
import java.awt.Color;
import java.util.List;

/**
 * Represents all the data needed to make a TilePack
 */
public class TilePack {
    public Integer id;
    public String packName;
    public String link;
    public String packTiles;
    public transient List<GroundMarkerPoint> parsedPackTiles;
    @Nullable
    public Color defaultColor;
    public boolean visible = true;

    public TilePack() {
    }

    public TilePack(Integer id, String packName, String packTiles) {
        this.id = id;
        this.packName = packName;
        this.packTiles = packTiles;
    }

    public TilePack(Integer id, String packName, String link, String packTiles) {
        this.id = id;
        this.packName = packName;
        this.link = link;
        this.packTiles = packTiles;
    }

    public TilePack(Integer id, boolean visible) {
        this.id = id;
        this.visible = visible;
    }

    public int indexOf(WorldPoint point) {
        for (int i = 0; i < parsedPackTiles.size(); i++) {
            if(parsedPackTiles.get(i).matchesLocation(point)) {
                return i;
            }
        }
        return -1;
    }
}

