    @Test
    public void defaultColorIsSavedReloadedAndOldRecordsRemainNull() {
        ConfigManager configManager = mockConfigManager();
        Map<String, String> values = new HashMap<>();
        values.put("pack_10005", "{\"id\":10005,\"packName\":\"Legacy\",\"packTiles\":\"[]\"}");
